cd "$(dirname "$0")/../../../instance/src/Core" || exit 1
for p in 'ENGINE *= *InnoDB' 'CREATE TABLE' 'ALTER TABLE' 'JSON_VALID' 'ON UPDATE CURRENT_TIMESTAMP' 'GENERATED ALWAYS|VIRTUAL|STORED' 'CREATE TRIGGER|createTrigger' 'ON DUPLICATE KEY' 'INSERT IGNORE' 'ALGORITHM' 'SHOW (COLUMNS|INDEX|TABLES|CREATE|FULL)' 'information_schema' 'JSON_EXTRACT|JSON_UNQUOTE|JSON_SET|JSON_OBJECT|JSON_ARRAY' 'UNHEX|HEX\(' 'FOREIGN_KEY_CHECKS' 'IFNULL|GROUP_CONCAT' 'FULLTEXT' 'REGEXP' 'UNIX_TIMESTAMP|DATE_FORMAT|NOW\(\)' 'MODIFY|CHANGE COLUMN' 'AUTO_INCREMENT' 'AddColumnTrait' 'ColumnExistsTrait' 'InheritanceUpdaterTrait' 'MakeVersionableMigrationHelper' 'dropForeignKeyIfExists|dropIndexIfExists|dropColumnIfExists' 'indexExists|columnExists' 'Uuid::fromHexToBytes|Uuid::randomBytes' 'registerIndexer'; do
 echo "$p => $(/usr/bin/grep -rliE "$p" Migration --include='*.php' | wc -l)"; done
